"""Editorial content for both languages. No unverified download or DOI URLs."""
from html import escape
import json

def pages(w):
    t, a, url, tag, note, table, cards = (w.t, w.a, w.url, w.tag, w.note, w.table, w.cards)
    result = []

    def add(path, en, zh, intro_en, intro_zh, body, kicker=None):
        title = t(en, zh)
        intro = t(intro_en, intro_zh)
        result.append((path, title, intro, w.heading(kicker or t('VALUE / RESOURCES', 'VALUE / 研究资源'), title, intro) + body))

    def section(title, body, id=''):
        return f'<section class="page-section"' + (f' id="{id}"' if id else '') + f'><h2>{title}</h2>{body}</section>'

    def para(en, zh):
        return '<p>' + t(en, zh) + '</p>'

    def steps(items):
        return '<ol>' + ''.join(('<li>' + x + '</li>' for x in items)) + '</ol>'

    def links(items):
        return '<div class="actions">' + ''.join((a(p, en, zh, 'button button-outline') for p, en, zh in items)) + '</div>'
    add('models', 'VALUE system modelling', 'VALUE 电力系统建模', 'Operation and investment evolution within explicit system boundaries.', '在明确系统边界下研究运行与投资演化。', w.product_cards())
    body = f'<div class="feature-split"><div><h2>{t('Operation informs investment.', '运行结果，反馈投资决策。')}</h2>' + para('VALUE connects operational simulation with investment decisions across years. A study describes the scenario; a run records one execution and its results.', 'VALUE 将运行模拟与跨年度投资决策连接起来。Study 保存研究配置，Run 记录一次具体执行与结果。') + para('The research boundary is explicit: technologies, demand, network representation and investment assumptions belong to a particular study configuration.', '技术对象、需求、网络表示与投资假设都属于具体研究配置，模型边界随配置清晰披露。') + links([('docs/value', 'Read the guide', '阅读使用指南'), ('releases?product=value', 'Release status', '查看发布状态')]) + '</div>' + w.diagram() + '</div>'
    body = body.replace('/releases?product=value/', '/releases/?product=value')
    body += section(t('A cycle across three stages', '三个阶段组成年度循环'), cards([(t('Define the study', '定义研究'), t('Set inputs, scenario assumptions, configuration and module versions before launching a run.', '明确输入、情景假设、研究配置和模块版本，再启动运行。'), ''), (t('Simulate operation', '模拟运行'), t('Represent half-hourly dispatch, storage operation and settlement within the configured network boundary.', '在选定的网络边界内，模拟半小时调度、储能运行与结算。'), ''), (t('Update the system', '更新系统'), t('Use operational outcomes in annual investment decisions, then carry the changed assets into the next year.', '将运行结果用于年度投资决策，再以变化后的资产进入下一年。'), '')]))
    body += section(t('Configurations are part of the method', '配置也是方法的一部分'), table([t('Configuration', '配置'), t('What it represents', '表示什么'), t('What it does not establish', '不能据此推断')], [(t('National baseline', '全国基线'), t('System-level operation and investment with a national boundary.', '全国边界下的系统运行与投资。'), t('Engineering repeatability is not a global optimality proof.', '工程可重复性不等于全局最优证明。')), (t('GB zonal study', '英国分区研究'), t('A fixed, lossless transport representation: 23 zones, 22 corridors and two boundary constraints.', '固定、无损的分区输电表示：23 个区域、22 条通道与两项边界约束。'), t('This configuration is not an AC power-flow or N−1 security study.', '此配置不是交流潮流或 N−1 安全分析。'))]))
    body += note(t('Read the evidence with its scope', '连同范围一起阅读验证结果'), t('The 2025–2034 national baseline completed 175,200 half-hour periods and repeated settlement hashes in engineering checks. The claim applies to that baseline, not every model configuration.', '2025–2034 全国基线完成 175,200 个半小时时段，工程复跑结算哈希一致。这一结论仅适用于该基线，不覆盖所有模型配置。'))
    body += links([('studies/national-baseline', 'National baseline', '全国基线案例'), ('validation', 'Validation & limitations', '验证与限制'), ('cite', 'Cite this product', '引用此产品')])
    add('models/value', 'Power systems, evolving.', '电力系统，持续演化。', 'Connect half-hourly operation with annual investment decisions.', '连接半小时运行与年度投资决策。', body, 'VALUE / ' + t('SYSTEM EVOLUTION', '系统演化'))
    study_data = [('value-101', 'value', 'VALUE 101', t('A first day in the model', '理解模型中的一天'), t('One day, 48 half-hour periods and synthetic teaching data.', '一天、48 个半小时时段与合成教学数据。'), t('Teaching materials · release pending', '教学材料 · 待公开发布')), ('national-baseline', 'value', t('National baseline', '全国十年基线'), t('Follow a decade of system evolution', '追踪十年的系统演化'), t('2025–2034 operation and annual investment, with scoped engineering repeatability evidence.', '2025–2034 年运行与投资，附有范围明确的工程可重复性证据。'), t('Engineering checks completed', '基线工程检查已完成')), ('gb-zonal', 'value', t('GB zonal study', '英国分区研究'), t('Give the network a boundary', '为网络约束明确边界'), t('23 zones and a fixed transport network. Validation is tracked independently from the national baseline.', '23 个区域与固定输电网络，验证状态独立于全国基线。'), t('Validation in progress · snapshot', '验证进行中 · 状态快照'))]
    body = '<div class="filter-bar" role="group" aria-label="' + t('Filter by product', '按产品筛选') + '">' + ''.join((f'<button class="filter-button" data-study-filter="{v}" aria-pressed="{str(v == 'all').lower()}">{label}</button>' for v, label in [('all', t('All studies', '全部案例')), ('value', 'VALUE')])) + '</div><p class="sr-only" data-filter-status aria-live="polite"></p><div class="study-grid">'
    for slug, prod, title, sub, desc, status in study_data:
        body += f'<article class="content-card" data-study-product="{prod}"><p class="eyebrow">{prod.upper()}</p><h2 style="font-size:1.8rem">{title}</h2><h3>{sub}</h3><p>{desc}</p><div class="meta-row">{tag(status, status)}</div>{a('studies/' + slug, 'Read study', '阅读案例')}</article>'
    body += '</div>' + note(t('Readiness is specific to each study', '案例状态逐项披露'), t('Public materials, engineering checks, scientific review and reproducibility conditions are recorded separately. A completed run alone does not establish scientific validity.', '材料公开、工程检查、科学审阅与复现条件分别记录。一次运行完成，并不能单独证明科学有效性。'))
    add('studies', 'Start with a study.', '从一个案例开始。', 'Understand the question, the configuration and the evidence before running the model.', '先了解研究问题、配置与证据，再开始运行模型。', body, t('STUDIES / LEARN BY REPRODUCING', '案例 / 从复现中学习'))

    def study_page(slug, title, zh, intro, zhintro, sections, status):
        body = '<div class="meta-row">' + tag(status[0], status[1]) + tag('Evidence snapshot · 2 October 2026', '证据快照 · 2026年10月2日') + '</div>'
        for h, p in sections:
            body += section(h, p)
        body += links([('releases', 'Software availability', '软件发布状态'), ('data', 'Data & licences', '数据与许可'), ('cite', 'Citation guidance', '引用说明')])
        add('studies/' + slug, title, zh, intro, zhintro, body, t('STUDY / CONFIGURATION & EVIDENCE', '案例 / 配置与证据'))
    study_page('value-101', 'VALUE 101: one day, 48 steps.', 'VALUE 101：一天，48 个时段。', 'A synthetic teaching case for understanding inputs, operations and result interpretation.', '用合成教学案例理解输入、运行与结果解释。', [(t('The research question', '研究问题'), para('How do the model’s inputs and choices flow into half-hourly operation? The teaching case reduces the time scope so you can inspect a full day before attempting a longer study.', '模型输入与选择如何传递到半小时运行？教学案例缩小时间范围，让你在长期研究之前先理解完整的一天。')), (t('Reproduction sequence', '复现顺序'), steps([t('Obtain a matching VALUE software release and its VALUE 101 teaching package.', '获取版本匹配的 VALUE 软件与 VALUE 101 教学包。'), t('Check the package README, data licence, environment and input identity.', '核对包内 README、数据许可、运行环境与输入身份。'), t('Create or open the teaching Study, confirm its 48 periods and explicitly start a Run.', '创建或打开教学 Study，确认 48 个时段，再显式启动 Run。'), t('Inspect the result tables and compare against the reference bundled with that exact release.', '查看结果表，并与该版本随附的参考结果比较。')]) + a('docs/value', 'Read the installation and workflow guide', '阅读环境与工作流程指南')), (t('Materials and limits', '材料与边界'), para('The synthetic teaching data carries CC0. Public download packaging is pending. The case is an instructional example, not a calibrated forecast for an actual power system.', '合成教学数据使用 CC0 许可。公开下载包仍待发布。此案例用于教学，不是对真实电力系统经过校准的预测。'))], ('Teaching case', '教学案例'))
    study_page('national-baseline', 'A decade of system evolution.', '十年的系统演化。', 'VALUE national baseline, 2025–2034.', 'VALUE 全国基线，2025–2034。', [(t('Question and configuration', '研究问题与配置'), para('Explore the interaction between system operation and annual investment over ten years. The baseline’s input and module identities matter: changing either creates a different experiment.', '研究十年间系统运行与年度投资的相互作用。输入与模块身份是基线的一部分，更改其中任何一项都会形成不同实验。')), (t('Engineering evidence', '工程证据'), table([t('Check', '检查'), t('Recorded outcome', '记录结果')], [(t('Time coverage', '时间覆盖'), t('175,200 half-hour periods completed for 2025–2034.', '2025–2034 年共 175,200 个半小时时段已完成。')), (t('Repeatability', '可重复性'), t('A rerun produced identical settlement hashes for the baseline.', '基线复跑的结算哈希一致。')), (t('Interpretation', '解释范围'), t('Repeatable execution under the tested configuration.', '在已测试配置下的执行可重复性。'))])), (t('Use the evidence correctly', '正确使用验证证据'), para('These checks do not establish global optimality, predictive accuracy or policy validity. Scientific interpretation requires the underlying assumptions, data and independent review. Public reproduction also depends on software and data availability.', '上述检查不证明全局最优、预测精度或政策有效性。科学解释仍需结合假设、数据与独立审阅；公开复现还取决于软件与数据是否可获得。') + a('validation', 'Read the validation record', '查看验证记录'))], ('Baseline engineering checks completed', '基线工程检查已完成'))
    study_page('gb-zonal', 'Represent a constrained network.', '表示一个受限的网络。', 'A GB zonal research configuration for VALUE.', 'VALUE 的英国分区研究配置。', [(t('Network representation', '网络表示'), para('This case uses 23 zones, 22 corridors and two boundary constraints, with a fixed, lossless zonal transport formulation. Treat that representation as part of the study’s assumptions.', '本案例使用 23 个区域、22 条通道与两项边界约束，采用固定、无损的分区输电表示。这一网络表示本身就是研究假设的一部分。')), (t('Evidence status', '证据状态'), para('The record used for this website snapshot reports longer-horizon validation in progress. It does not inherit the national baseline’s completion status. No completed ten-year zonal result is asserted here.', '本网站快照所依据的记录显示，较长时间范围验证仍在进行。它不继承全国基线的完成状态；此处不声明分区十年结果已经完成。')), (t('Interpretation boundary', '解释边界'), para('The case is not an AC power-flow calculation or an N−1 security assessment. Results should be reported with network assumptions, capacities, scenario identity and validation evidence.', '此案例不是交流潮流计算，也不是 N−1 安全评估。结果须附带网络假设、通道容量、情景身份与验证证据。'))], ('Validation in progress · dated snapshot', '验证进行中 · 有日期的快照'))
    selector = f'<div class="release-controls"><label class="field">{t('Product', '产品')}<select aria-label="{t('Product', '产品')}" data-product-select><option value="value">VALUE</option></select></label><label class="field">{t('Version', '版本')}<select disabled aria-label="{t('No public release yet', '尚无公开版本')}"><option>{t('Public release pending', '公开版本待发布')}</option></select></label><label class="field">{t('Platform', '平台')}<select aria-label="{t('Platform', '平台')}" data-platform-select><option value="linux">Linux x86_64</option><option value="windows">Windows x64</option><option value="macos-x64">macOS Intel</option><option value="macos-arm64">macOS Apple Silicon</option></select></label></div>'
    body = '<p>' + a('release-check', 'Installation guide and package status', '安装指南与软件包状态', 'button') + '</p><div class="release-panel">' + selector
    for prod in w.CONFIG['products']:
        single = False
        body += f'<div data-product-panel="{prod['id']}"' + (' hidden' if single else '') + '><div class="status-panel">' + tag('Public release pending', '公开版本待发布') + f'<h2 style="font-size:1.8rem;margin:16px 0">{prod['name']}</h2>'
        body += para('No verified public release files are available yet. Published versions will appear here with a fixed download link, file size, SHA256 checksum and matching documentation.', '尚无经核验的公开版本文件。发布后，此处将显示固定下载地址、文件大小、SHA256 校验和与匹配文档。')
        body += f'<p data-platform-note="linux">{t('Linux: Full 2026-10-03-rc1 includes private Python and Node; offline installation and scoped four-role tasks passed.', 'Linux：Full 2026-10-03-rc1 内置 Python、Node，断网安装及指定四角色短任务通过。')}</p><p data-platform-note="windows" hidden>{t('Windows 10+ x64: Full 2026-10-03-rc1 includes its runtime and install-value.cmd; native validation and signing are pending.', 'Windows 10+ x64：Full 2026-10-03-rc1 自带环境，使用 install-value.cmd；实机验收及签名待完成。')}</p><p data-platform-note="macos-x64" hidden>{t('macOS 15+ Intel: Full 2026-10-03-rc1 includes its own runtime. Native acceptance, signing and notarisation are pending.', 'macOS 15+ Intel：Full 2026-10-03-rc1 自带环境；实机验收、签名与公证待完成。')}</p><p data-platform-note="macos-arm64" hidden>{t('macOS 15+ Apple Silicon: a separate arm64 Full 2026-10-03-rc1 archive includes its own runtime. Native acceptance, signing and notarisation are pending.', 'macOS 15+ Apple Silicon：提供独立 arm64 Full 2026-10-03-rc1 包及环境；实机验收、签名与公证待完成。')}</p>'
        body += '</div><div class="release-links">' + a('docs/' + prod['id'], 'Read product guide', '阅读产品指南') + a('validation', 'Validation record', '验证记录') + a('cite', 'Citation information', '引用信息') + '</div>'
        for release in prod['releases']:
            body += f'<article class="content-card published-release" data-release-platform="{escape(release['platform'])}"><h3>{escape(release['version'])}</h3><p>{escape(release['date'])} · {escape(release['size'])}</p><p>{escape(release['requirements'])}</p><a class="button" href="{escape(release['url'])}">{t('Download from GitHub', '从 GitHub 下载')}</a><p class="small">SHA256</p><pre class="code-box">{escape(release['sha256'])}</pre></article>'
        body += '</div>'
    body += '</div>'
    body += section(t('Download only what you need', '按需获取材料'), cards([(t('Software & smallest example', '软件与最小示例'), t('Start with the product package and a short example for the same version.', '先获取同一版本的产品软件包与短示例。'), a('docs', 'Read the guides', '阅读指南')), (t('Study data', '研究数据'), t('Follow each dataset’s licence and version. Large research data is distributed independently.', '按每个数据集的许可与版本获取。大型研究数据独立分发。'), a('data', 'Explore data access', '查看数据获取方式')), (t('Record the version', '记录研究版本'), t('Keep the software, configuration, data identities and any verified citation with your study.', '随研究保存软件、配置、数据身份及经核实的引用条目。'), a('cite', 'Prepare a citation', '准备引用'))]))
    body += note(t('Direct distribution', '直接分发'), t('value.ac is the installation entry point. Installers and redistributable large data packages are hosted in the Value repository’s GitHub Releases. Downloads go directly to the selected version; model computation and results stay on your computer.', 'value.ac 是安装入口；完整安装包和获准分发的大数据包托管在 Value 仓库的 GitHub Releases。下载直达所选版本，模型计算和结果保留在用户本机。'))
    add('releases', 'Install VALUE on your computer.', '在电脑上安装 VALUE。', 'Choose your product and platform here, download the package and run its installer locally.', '在这里选择产品和平台，下载完整包，再在本机运行安装器。', body, t('DOWNLOADS / RELEASES', '下载 / 软件版本'))
    body = table([t('Material', '材料'), t('Access and licence', '获取与许可'), t('Distribution', '分发方式')], [('VALUE 101', t('Three synthetic teaching and contract packs are public under CC0 in the Value repository.', '三个 CC0 合成教学与契约数据包已在 Value 仓库公开。'), t('Small example with the matching software release.', '随匹配软件版本提供小型示例。')), (t('Full study data', '完整研究数据'), t('Licence and source depend on the dataset. UK data may require separate permission.', '按具体数据集确认许可与来源。UK 数据可能需要独立授权。'), t('Authorised source; preprocessing and input identity recorded per study.', '授权来源；每项研究记录预处理过程与输入身份。')), (t('Large public datasets', '大型公开数据'), t('Archive and data version must be verified before listing.', '列出前核验归档与数据版本。'), t('Versioned GitHub Releases in hanzohanzhe/Value; select them through value.ac.', '托管在 hanzohanzhe/Value 的版本化 GitHub Releases，通过 value.ac 选择下载。')), (t('Your research outputs', '用户研究结果'), t('Stored and managed by the researcher.', '由研究者保存和管理。'), t('Your local or research compute storage, not the website.', '本地或研究计算存储，不进入官网。'))])
    body += section(t('What every dataset needs', '每个数据集都需要'), cards([(t('Identity', '身份'), t('Source, version, time coverage, units and the study that uses it.', '来源、版本、时间覆盖、单位与使用它的研究。'), ''), (t('Permission', '许可'), t('A data licence and redistribution conditions, independently of the software licence.', '独立于软件许可的数据许可与再分发条件。'), ''), (t('Integrity', '完整性'), t('File size and SHA256 for downloadable archives, with a fixed version link.', '可下载归档的体积、SHA256 校验和与固定版本链接。'), '')]))
    body += note(t('Software openness does not relicense data', '软件开源不会改变数据许可'), t('An Apache-2.0 software licence does not grant permission to redistribute third-party data. Obtain restricted datasets from their authorised source.', 'Apache-2.0 软件许可不会赋予第三方数据的再分发权。受限数据应从其授权来源获取。'))
    body += '<p>' + w.external('https://github.com/hanzohanzhe/Value/tree/main/data-packs', t('Browse the three published synthetic data packs', '查看三个已公开的合成数据包')) + '</p>'
    add('data', 'Data, with its provenance.', '让数据带着来源。', 'Obtain the smallest relevant dataset, with its own licence and exact version.', '获取所需的最小数据集，并保留其独立许可与准确版本。', body, t('RESOURCES / DATA', '资源 / 数据'))
    body = table([t('Product / configuration', '产品 / 配置'), t('Engineering evidence', '工程证据'), t('Limit of the claim', '结论边界')], [(t('VALUE national baseline', 'VALUE 全国基线'), t('2025–2034 completed; 175,200 half-hours; rerun settlement hashes identical.', '2025–2034 已完成；175,200 个半小时；复跑结算哈希一致。'), t('Applies to the tested baseline. Not a global optimality or policy-validity claim.', '适用于已测试基线，不构成全局最优或政策有效性结论。')), (t('VALUE four user paths', 'VALUE 四条用户路径'), t('Four specified tasks passed after fixes on 2 October 2026. Reproduction, data adaptation and module modification: 48 periods each. Observer extension: 2 periods.', '2026年10月2日，四项指定任务修复后通过。复现、换数据、改模块各 48 时段；observer 扩展为 2 时段。'), t('Short-scope usability and wiring checks; not full-year scientific validation.', '短范围可用性与接线检查，不是全年科学验证。')), (t('VALUE GB zonal study', 'VALUE 英国分区研究'), t('Longer-horizon validation in progress in the source snapshot.', '依据记录快照，较长时间范围验证仍在进行。'), t('Does not inherit the national baseline’s status; fixed lossless transport representation.', '不继承全国基线的状态；采用固定无损输电表示。'))])
    body += note(t('Evidence snapshot · 2 October 2026', '证据快照 · 2026年10月2日'), t('This page records a dated research status, not a live progress monitor. Later releases may supersede it. Engineering completion, scientific review and public availability are tracked separately.', '本页记录有日期的研究状态，不是实时进度监控。后续版本可能更新此记录。工程完成、科学审阅与公开可获得性分别记录。'))
    body += section(t('Four questions for every study', '每项研究都回答四个问题'), cards([(t('What was tested?', '测试了什么？'), t('Identify the product, configuration, software version and test horizon.', '明确产品、配置、软件版本与测试时间范围。'), ''), (t('What can be reproduced?', '什么可以复现？'), t('Check access to software, inputs, reference outputs and an appropriate environment.', '核对软件、输入、参考输出与运行环境是否可获得。'), ''), (t('What has been reviewed?', '哪些结论经过审阅？'), t('State whether the scientific interpretation has independent review. Do not infer it from execution success.', '说明科学解释是否经过独立审阅，不从执行成功推断科学结论成立。'), ''), (t('What is public?', '哪些材料已经公开？'), t('List the available code, input data, reference results and their access conditions.', '列出已公开的代码、输入数据、参考结果与获取条件。'), '')], 'path-grid'))
    body += links([('studies', 'Study records', '案例记录'), ('releases', 'Release availability', '发布状态')])
    add('validation', 'Know what the evidence supports.', '了解证据能够支持什么。', 'Validation belongs to a product, configuration and version—not to a brand name alone.', '验证对应具体产品、配置与版本，每项结论都需要明确范围。', body, t('RESEARCH / VALIDATION & LIMITS', '研究 / 验证与限制'))
    bib = '@software{xing_value_2026,\n  author = {Xing, Hanzhe},\n  title = {{VALUE Network Extensions}: Variable renewable electricity Allocation, Load-enabled excess-generation Utilisation, and system Evolution},\n  version = {0.6.0-alpha.2},\n  date = {2026-08-20},\n  note = {Research preview; cite the exact software used}\n}'
    body = '<div class="release-panel"><div class="release-controls"><label class="field">' + t('Product', '产品') + '<select aria-label="' + t('Product', '产品') + '" data-product-select><option value="value">VALUE</option></select></label></div>'
    body += '<section class="content-section" data-product-panel="value"><h2>VALUE · source-2026-10-04</h2>' + para('The clean source snapshot in hanzohanzhe/Value has its own citation. Record the exact commit used; it is distinct from the Full installer candidate and historical software metadata.', 'hanzohanzhe/Value 中的干净源码快照具有独立引用。请记录实际使用的 commit；它与完整安装候选和历史软件元数据分别对应。') + '<p><a download href="/assets/value-source-review-CITATION.cff">CITATION.cff</a></p></section>'
    body += note(t('Recommended research citation', '建议研究引用'), t('Citation is recommended for research reporting and is not an additional software licence condition.', '建议在研究成果中引用项目；学术引用不是软件许可的附加条件。'))
    candidate_bib = (w.ROOT / 'static/assets/release-candidate/CITATION.bib').read_text()
    body += '<section class="content-section" data-product-panel="value"><h2>VALUE · 2026-10-03-rc1</h2>' + para('Current full-installation candidate. This citation identifies the local distribution, not a published tag or DOI. The inherited source metadata below has a separate historical identity.', '当前完整安装候选。此引用标识本地分发批次，不代表已发布 tag 或 DOI；下方保留的旧源码元数据属于另一历史身份。') + '<pre class="code-box">' + escape(candidate_bib) + '</pre><p><a download href="/assets/release-candidate/CITATION.cff">CITATION.cff</a> · <a download href="/assets/release-candidate/CITATION.bib">BibTeX</a></p></section>'
    body += '<div data-product-panel="value">' + tag('Historical source metadata', '历史源码元数据') + '<h2 style="font-size:1.8rem;margin:20px 0">VALUE Network Extensions · 0.6.0-alpha.2</h2>' + para('The historical August source CITATION.cff names “VALUE Network Extensions”, authored by Hanzhe Xing, version 0.6.0-alpha.2, dated 20 August 2026. This is not a claim that the October installation candidates are already published. No DOI is assigned in the verified metadata.', '历史八月源码 CITATION.cff 题名为“VALUE Network Extensions”，作者为 Hanzhe Xing、版本 0.6.0-alpha.2、日期 2026年8月20日。这不表示十月安装候选包已公开发布。已核实元数据中没有 DOI。') + f'<pre class="code-box" id="value-bibtex">{escape(bib)}</pre><div class="actions"><button class="button" data-copy="value-bibtex" data-feedback="cite-feedback">{t('Copy BibTeX', '复制 BibTeX')}</button><a class="button button-outline" href="/assets/value-source-metadata.bib" download>{t('Download .bib', '下载 .bib')}</a><a class="button button-outline" href="/assets/value-source-CITATION.cff" download>{t('Download CITATION.cff', '下载 CITATION.cff')}</a></div><p class="copy-feedback" id="cite-feedback" aria-live="polite"></p></div>'
    body += section(t('Cite the complete research record', '引用完整的研究记录'), steps([t('Use the exact software product and version actually used. Prefer its verified version DOI when available.', '引用实际使用的软件产品与准确版本；已有经核验的版本 DOI 时优先使用。'), t('Record the study configuration and relevant method references.', '记录研究配置及相关方法文献。'), t('Cite datasets separately using their own authors, versions and persistent identifiers.', '使用数据集自身的作者、版本和持久标识独立引用数据。'), t('Retain input hashes and run identifiers in your reproducibility materials.', '在复现材料中保留输入哈希与运行标识。')]))
    body += note(t('A Star is not a citation', 'Star 不等于学术引用'), t('GitHub Stars show voluntary community support. Software and data citations identify what a study used. Neither should replace the other.', 'GitHub Star 表达自愿的社区支持；软件与数据引用标识研究使用的具体材料，两者不能互相替代。'))
    add('cite', 'Make your research traceable.', '让研究可以追溯。', 'Keep software, study and data identities together.', '同时保留软件、研究配置与数据身份。', body, t('PROJECT / CITATION', '项目 / 引用'))
    (w.DIST / 'assets' / 'value-source-metadata.bib').write_text(bib + '\n')
    archive = w.external('https://github.com/hanzohanzhe/SCHEME-C-PhD-Reproduction', t('Open historical research archive on GitHub', '在 GitHub 查看历史研究档案'))
    body = section(t('The name', '名称的含义'), para('VALUE stands for Variable renewable electricity Allocation, Load-enabled excess-generation Utilisation, and system Evolution. The website presents power-system operation and investment evolution.', 'VALUE 全称为 Variable renewable electricity Allocation, Load-enabled excess-generation Utilisation, and system Evolution。官网介绍电力系统运行与投资演化。'))
