    body += note(t('Software licence', '软件许可'), t('VALUE software use Apache-2.0, including commercial use under its terms. Documentation uses CC BY 4.0; VALUE 101 synthetic data uses CC0; third-party dependencies and datasets retain their own terms. Research citation is recommended and is not an additional condition for using the software.', 'VALUE 软件均采用 Apache-2.0，可依其条款用于商业用途。文档采用 CC BY 4.0，VALUE 101 合成数据采用 CC0；第三方依赖与数据保留各自条款。建议在研究成果中引用项目，学术引用不是软件使用的附加条件。'))
    body += section(t('Distribution and permanent references', '分发与持久引用'), para('The website is lightweight. Public source and software releases will be distributed through GitHub; independent archives can preserve public research data and versioned software records. Links are added only after the actual files, licence and citation metadata are checked.', '官网保持轻量。公开源码与软件版本将通过 GitHub 分发；独立归档可保存公开研究数据和有版本的软件记录。只有实际文件、许可与引用元数据核验后才会接入链接。') + '<p>' + w.external('https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases', t('GitHub Releases documentation', 'GitHub Releases 官方说明')) + ' · ' + w.external('https://help.zenodo.org/docs/github/archive-software/github-upload/', t('Zenodo software archiving', 'Zenodo 软件归档')) + '</p>')
    add('about', 'Research with explicit assumptions.', '让研究假设清晰可见。', 'Models, materials and evidence that stay connected.', '让模型、材料与证据保持关联。', body, t('PROJECT / ABOUT VALUE', '项目 / 关于 VALUE'))
    updated = []
    for path, title, desc, body in result:
        if path in {'models/value', 'docs', 'docs/value', 'data', 'validation', 'studies/national-baseline', 'studies/gb-zonal', 'studies/site-design', 'cite'}:
            note_body = t('Read the audited equations, numerical parameters, pseudocode and initial dataset identities. The complete methodology distinguishes implementation, tested examples and remaining reproducibility gaps.', '查看已对照源码的公式、数值参数、伪代码与初始数据身份。完整方法学区分实际实现、已验证小例与尚未补齐的复现条件。')
